window.TEST_PARTS=window.TEST_PARTS||{};window.TEST_PARTS["test7"]=(window.TEST_PARTS["test7"]||[]).concat([{"n":154,"q":"Թույլատրվու՞մ է արդյոք զբոսաշրջային ավտոբուսի վարորդին կանգառ կատարել նշված վայրում, եթե հեռավորությունը մինչև հետիոտնային անցում 3մետր է։","options":["Այո","Ոչ"],"ans":2,"page":57,"images_inline":["data:image/jpeg;base64,"]},{"n":155,"q":"Ո՞ր վարորդն է խախտել կանգառ կատարելու կանոնները։","options":["Ավտոբուսի վարորդը","Մոտոցիկլի վարորդը","Ոչ մեկը","Երկու վարորդները"],"ans":4,"page":57,"images_inline":["data:image/jpeg;base64,"]},{"n":156,"q":"Ավտոբուսների կայանումը արգելվում է","options":["երթևեկելի մասի եզրին՝ կողնակի բացակայության դեպքում։","բնակավայրից դուրս << Գլխավոր ճանապարհ>> ճանապարհային նշանով նշված ճանապարհների երթևեկելի մասի վրա։","հատվող երթևեկելի մասերի եզրից 10մ հեռավորության վայրում։"],"ans":2,"page":57},{"n":157,"q":"Ընդհանուր օգտագործման տրանսպորտային միջոցներին թույլատրվու՞մ է կանգառի կետերից դուրս կանգառ կատարել:","options":["Թույլատրվում է ուղևորի պահանջի դեպքում","Թույլատրվում է հարկադրված կանգառի դեպքում"],"ans":2,"page":57},{"n":158,"q":"Օրվա մութ ժամանակ ճանապարհի չլուսավորված հատվածներում կանգառի կամ կայանման դեպքում ավտոբուսների վրա պետք է միացված լինեն","options":["եզրաչափային լույսերը։","մոտակա լույսերը։","հակամառախուղային լապտերները։"],"ans":1,"page":58},{"n":159,"q":"Այս նշանի առկայության դեպքում կանգառը թույլատրվում է","options":["միայն ավտոբուսներին։","ավտոբուսներին և (կամ) տրոլեյբուսներին։","միայն տրոլեյբուսներին։"],"ans":2,"page":58,"images_inline":["data:image/jpeg;base64,"]},{"n":160,"q":"Այս նշանի առկայության դեպքում կանգառը թույլատրվում է","options":["ավտոբուսներին և (կամ) տրոլեյբուսներին։","միայլ տրամվայներին։","տրամվայներին և տրոլեյբուսներին։"],"ans":2,"page":58,"images_inline":["data:image/jpeg;base64,"]},{"n":161,"q":"Թույլատրվու՞մ է ավտոբուսի վարորդին ուղևոր վերցնելու համար կանգառ կատարել կամրջի վրա։","options":["Թույլատրվում է","Թույլատրվում է միայն «D1» ենթակարգի ավտոբուսներին","Արգելվում է"],"ans":3,"page":59,"images_inline":["data:image/jpeg;base64,"]},{"n":162,"q":"Ո՞ր ավտոբուսի վարորդն է խախտել կայանման կանոնները։","options":["Միայն կանաչ ավտոբուսի վարորդը","Միայն դեղին ավտոբուսի վարորդը","Երկու ավտոբուսների վարորդները"],"ans":2,"page":59,"images_inline":["data:image/jpeg;base64,"]},{"n":163,"q":"Երթուղային ավտոբուսի վարորդը այս խաչմերուկում ձախ շրջադարձ կատարելուց հետո պետք է կանգառ կատարի սահմանված կետում ուղևորների նստեցման և իջեցման համար։ Ո՞ր հետագծով նա պետք է կատարի ձախ շրջադարձը։","options":["Միայն A հետագծով","Միայն B հետագծով, քանի որ կանգառի կետը գտնվում է ճանապարհի աջ կողմում","Ցանկացած հետագծով"],"ans":3,"page":59,"images_inline":["data:image/jpeg;base64,"]}]);